fn decode_sve_fp_fcadd(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff3ee000 != 0x64008000 {
        return Err(DecodeError::Unallocated);
    }
    // 011|0010|0|size=xx|00000|rot=x|100|Pg=xxx|Zm=xxxxx|Zdn=xxxxx
    // FCADD  <Zdn>.<T>, <Pg>/M, <Zdn>.<T>, <Zm>.<T>, <const>
    let size: u8 = ((bits >> 22) & 0x3) as u8;
    if size == 0b00 {
        return Err(DecodeError::UNDEF);
    }
    let Pg: u8 = ((bits >> 10) & 0x7) as u8;
    let Zdn: u8 = (bits & 0x1f) as u8;
    let Zm: u8 = ((bits >> 5) & 0x1f) as u8;
    let rot: u8 = ((bits >> 16) & 0x1) as u8;
    Ok(Instruction::FcaddZPZz {
        Zdn: ZReg::new(Zdn),
        T: match size {
            0b01 => Arrangement::element(ElementWidth::H),
            0b10 => Arrangement::element(ElementWidth::S),
            0b11 => Arrangement::element(ElementWidth::D),
            _ => return Err(DecodeError::Unallocated),
        },
        Pg: PReg::new(Pg),
        Zm: ZReg::new(Zm),
        const_: if rot == 0 { 90 } else { 270 },
    })
}

