fn decode_sve_int_count(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff30fc00 != 0x420e000 {
        return Err(DecodeError::Unallocated);
    }
    // 000|0010|0|size=xx|1|0|imm4=xxxx|11|100|op=0|pattern=xxxxx|Rd=xxxxx
    let Rd: u8 = (bits & 0x1f) as u8;
    let pattern: u8 = ((bits >> 5) & 0x1f) as u8;
    let imm4: u8 = ((bits >> 16) & 0xf) as u8;
    let imm: u8 = imm4 + 1;
    match bits & 0xc00400 {
        0 => {
            // CNTB, CNTD, CNTH, CNTW
            // CNTB  <Xd>{, <pattern>{, MUL #<imm>}}
            Ok(Instruction::CntbRS {
                Xd: Rd.into(),
                pattern,
                imm,
            })
        }
        0x400000 => {
            // CNTB, CNTD, CNTH, CNTW
            // CNTH  <Xd>{, <pattern>{, MUL #<imm>}}
            Ok(Instruction::CnthRS {
                Xd: Rd.into(),
                pattern,
                imm,
            })
        }
        0x800000 => {
            // CNTB, CNTD, CNTH, CNTW
            // CNTW  <Xd>{, <pattern>{, MUL #<imm>}}
            Ok(Instruction::CntwRS {
                Xd: Rd.into(),
                pattern,
                imm,
            })
        }
        0xc00000 => {
            // CNTB, CNTD, CNTH, CNTW
            // CNTD  <Xd>{, <pattern>{, MUL #<imm>}}
            Ok(Instruction::CntdRS {
                Xd: Rd.into(),
                pattern,
                imm,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

