fn decode_sve_int_mov_p2v(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff39fe00 != 0x5293800 {
        return Err(DecodeError::Unallocated);
    }
    // 000|0010|1|opc=xx|1|01|opc2=xx|1|001110|0|Pn=xxxx|Zd=xxxxx
    if (bits & 0xc60000) == 0x20000 {
        // PMOV (to vector)
        // PMOV  <Zd>, <Pn>.B
        let Pn: u8 = ((bits >> 5) & 0xf) as u8;
        let Zd: u8 = (bits & 0x1f) as u8;
        Ok(Instruction::PmovZPiB {
            Zd: ZReg::new(Zd),
            Pn: PReg::new(Pn),
        })
    } else if (bits & 0xc40000) == 0x40000 {
        // PMOV (to vector)
        // PMOV  <Zd>{[<imm>]}, <Pn>.H
        let i1: u8 = ((bits >> 17) & 0x1) as u8;
        let Pn: u8 = ((bits >> 5) & 0xf) as u8;
        let Zd: u8 = (bits & 0x1f) as u8;
        Ok(Instruction::PmovZPiH {
            Zd: ZReg::new(Zd),
            imm: i1 != 0,
            Pn: PReg::new(Pn),
        })
    } else if (bits & 0xc00000) == 0x400000 {
        // PMOV (to vector)
        // PMOV  <Zd>{[<imm>]}, <Pn>.S
        let i2: u8 = ((bits >> 17) & 0x3) as u8;
        let Pn: u8 = ((bits >> 5) & 0xf) as u8;
        let Zd: u8 = (bits & 0x1f) as u8;
        Ok(Instruction::PmovZPiS {
            Zd: ZReg::new(Zd),
            imm: i2,
            Pn: PReg::new(Pn),
        })
    } else if (bits & 0x800000) == 0x800000 {
        // PMOV (to vector)
        // PMOV  <Zd>{[<imm>]}, <Pn>.D
        let Pn: u8 = ((bits >> 5) & 0xf) as u8;
        let Zd: u8 = (bits & 0x1f) as u8;
        let i3h: u8 = ((bits >> 22) & 0x1) as u8;
        let i3l: u8 = ((bits >> 17) & 0x3) as u8;
        let imm: i64 = (i3h << 2 | i3l) as i64;
        Ok(Instruction::PmovZPiD {
            Zd: ZReg::new(Zd),
            imm,
            Pn: PReg::new(Pn),
        })
    } else {
        Err(DecodeError::Unallocated)
    }
}

