fn decode_sve_int_perm_dup_i(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff20fc00 != 0x5202000 {
        return Err(DecodeError::Unallocated);
    }
    // 000|0010|1|imm2=xx|1|tsz=xxxxx|001000|Zn=xxxxx|Zd=xxxxx
    // MOV (SIMD&FP scalar, unpredicated)
    // MOV  <Zd>.<T>, <V><n>
    // MOV (SIMD&FP scalar, unpredicated)
    // MOV  <Zd>.<T>, <Zn>.<T>[<imm>]
    // DUP (indexed)
    // DUP  <Zd>.<T>, <Zn>.<T>[<imm>]
    let tsz: u8 = ((bits >> 16) & 0x1f) as u8;
    if tsz == 0b00000 {
        return Err(DecodeError::UNDEF);
    }
    let lsb: u8 = tsz.trailing_zeros().min(5) as u8;
    let imm2: u8 = ((bits >> 22) & 0x3) as u8;
    let imm: u8 = imm2 << 5 | tsz;
    let index: i64 = (imm >> (lsb + 1)) as i64;
    let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
    let Zd: u8 = (bits & 0x1f) as u8;
    if (imm2 << 5 | tsz).count_ones() == 1 {
        return Ok(Instruction::MovZVDupZZi {
            Zd: ZReg::new(Zd),
            T: match tsz {
                0x10 => Arrangement::element(ElementWidth::Q),
                0x8 | 0x18 => Arrangement::element(ElementWidth::D),
                v if v & 0x7 == 0x4 => Arrangement::element(ElementWidth::S),
                v if v & 0x3 == 0x2 => Arrangement::element(ElementWidth::H),
                v if v & 0x1 == 0x1 => Arrangement::element(ElementWidth::B),
                _ => return Err(DecodeError::Unallocated),
            },
            n: match tsz {
                0x10 => DynScalarSimd::Q(QReg::new(Zn)),
                0x8 | 0x18 => DynScalarSimd::D(DReg::new(Zn)),
                v if v & 0x7 == 0x4 => DynScalarSimd::S(SReg::new(Zn)),
                v if v & 0x3 == 0x2 => DynScalarSimd::H(HReg::new(Zn)),
                v if v & 0x1 == 0x1 => DynScalarSimd::B(BReg::new(Zn)),
                _ => return Err(DecodeError::Unallocated),
            },
        });
    }
    if (imm2 << 5 | tsz).count_ones() > 1 {
        return Ok(Instruction::MovZZiDupZZi {
            Zd: ZReg::new(Zd),
            T: match tsz {
                0x10 => Arrangement::element(ElementWidth::Q),
                0x8 | 0x18 => Arrangement::element(ElementWidth::D),
                v if v & 0x7 == 0x4 => Arrangement::element(ElementWidth::S),
                v if v & 0x3 == 0x2 => Arrangement::element(ElementWidth::H),
                v if v & 0x1 == 0x1 => Arrangement::element(ElementWidth::B),
                _ => return Err(DecodeError::Unallocated),
            },
            Zn: ZReg::new(Zn),
            imm: index,
        });
    }
    Ok(Instruction::DupZZi {
        Zd: ZReg::new(Zd),
        T: match tsz {
            0x10 => Arrangement::element(ElementWidth::Q),
            0x8 | 0x18 => Arrangement::element(ElementWidth::D),
            v if v & 0x7 == 0x4 => Arrangement::element(ElementWidth::S),
            v if v & 0x3 == 0x2 => Arrangement::element(ElementWidth::H),
            v if v & 0x1 == 0x1 => Arrangement::element(ElementWidth::B),
            _ => return Err(DecodeError::Unallocated),
        },
        Zn: ZReg::new(Zn),
        imm: index,
    })
}

