fn decode_sve_int_pred_dup(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff20c210 != 0x25204000 {
        return Err(DecodeError::Unallocated);
    }
    // 001|0010|1|i1=x|tszh=x|1|tszl=xxx|Rv=xx|01|Pn=xxxx|S=0|Pm=xxxx|0|Pd=xxxx
    if (bits & 0x200) == 0 {
        // PSEL  <Pd>, <Pn>, <Pm>.<T>[<Wv>, <imm>]
        let i1: u8 = ((bits >> 23) & 0x1) as u8;
        let tszh: u8 = ((bits >> 22) & 0x1) as u8;
        let tszl: u8 = ((bits >> 18) & 0x7) as u8;
        let imm5: u8 = i1 << 4 | tszh << 3 | tszl;
        let imm: i64 = if tszh == 0b0 && tszl == 0b000 {
            return Err(DecodeError::UNDEF);
        } else if tszl == 0b000 {
            (imm5 >> 4) as i64
        } else if tszl == 0b100 {
            (imm5 >> 3) as i64
        } else if (tszl & 0x3) == 0x2 {
            (imm5 >> 2) as i64
        } else {
            (imm5 >> 1) as i64
        };
        let Pn: u8 = ((bits >> 10) & 0xf) as u8;
        let Pm: u8 = ((bits >> 5) & 0xf) as u8;
        let Pd: u8 = (bits & 0xf) as u8;
        let Rv: u8 = ((bits >> 16) & 0x3) as u8;
        let v: u8 = 0b01100 | Rv;
        Ok(Instruction::PselPPpi {
            Pd: PReg::new(Pd),
            Pn: PReg::new(Pn),
            Pm: PReg::new(Pm),
            T: match tszh << 3 | tszl {
                0b1000 => Arrangement::element(ElementWidth::D),
                0b0100 | 0b1100 => Arrangement::element(ElementWidth::S),
                v if v & 0b0011 == 0b0010 => Arrangement::element(ElementWidth::H),
                v if v & 0b0001 == 0b0001 => Arrangement::element(ElementWidth::B),
                _ => return Err(DecodeError::Unallocated),
            },
            Wv: WRegZr::new(v),
            imm,
        })
    } else {
        Err(DecodeError::Unallocated)
    }
}

fn decode_sve_int_pred_log(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff30c000 != 0x25004000 {
        return Err(DecodeError::Unallocated);
    }
    // 001|0010|1|op=x|S=x|00|Pm=xxxx|01|Pg=xxxx|o2=x|Pn=xxxx|o3=x|Pd=xxxx
    let Pm: u8 = ((bits >> 16) & 0xf) as u8;
    let Pg: u8 = ((bits >> 10) & 0xf) as u8;
    let Pn: u8 = ((bits >> 5) & 0xf) as u8;
    let Pd: u8 = (bits & 0xf) as u8;
    match bits & 0xc00210 {
        0 => {
            // MOV (predicate, zeroing)
            // MOV  <Pd>.B, <Pg>/Z, <Pn>.B
            // AND (predicates)
            // AND  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            if Pn == Pm {
                return Ok(Instruction::MovzPPPAndPPPpZ {
                    Pd: PReg::new(Pd),
                    Pg: PReg::new(Pg),
                    Pn: PReg::new(Pn),
                });
            }
            Ok(Instruction::AndPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        16 => {
            // BIC (predicates)
            // BIC  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            Ok(Instruction::BicPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x200 => {
            // NOT (predicate)
            // NOT  <Pd>.B, <Pg>/Z, <Pn>.B
            // EOR (predicates)
            // EOR  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            if Pm == Pg {
                return Ok(Instruction::NotPPPZEorPPPpZ {
                    Pd: PReg::new(Pd),
                    Pg: PReg::new(Pg),
                    Pn: PReg::new(Pn),
                });
            }
            Ok(Instruction::EorPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x210 => {
            // MOV (predicate, merging)
            // MOV  <Pd>.B, <Pg>/M, <Pn>.B
            // SEL (predicates)
            // SEL  <Pd>.B, <Pg>, <Pn>.B, <Pm>.B
            if Pd == Pm {
                return Ok(Instruction::MovmPPPSelPPPp {
                    Pd: PReg::new(Pd),
                    Pg: PReg::new(Pg),
                    Pn: PReg::new(Pn),
                });
            }
            Ok(Instruction::SelPPPp {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x400000 => {
            // MOVS (predicated)
            // MOVS  <Pd>.B, <Pg>/Z, <Pn>.B
            // ANDS  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            if Pn == Pm {
                return Ok(Instruction::MovzsPPPAndsPPPpZ {
                    Pd: PReg::new(Pd),
                    Pg: PReg::new(Pg),
                    Pn: PReg::new(Pn),
                });
            }
            Ok(Instruction::AndsPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x400010 => {
            // BICS  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            Ok(Instruction::BicsPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x400200 => {
            // NOTS  <Pd>.B, <Pg>/Z, <Pn>.B
            // EORS  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            if Pm == Pg {
                return Ok(Instruction::NotsPPPZEorsPPPpZ {
                    Pd: PReg::new(Pd),
                    Pg: PReg::new(Pg),
                    Pn: PReg::new(Pn),
                });
            }
            Ok(Instruction::EorsPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x800000 => {
            // MOV  <Pd>.B, <Pn>.B
            // ORR (predicates)
            // ORR  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            if Pn == Pm && Pm == Pg {
                return Ok(Instruction::MovPPOrrPPPpZ {
                    Pd: PReg::new(Pd),
                    Pn: PReg::new(Pn),
                });
            }
            Ok(Instruction::OrrPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x800010 => {
            // ORN (predicates)
            // ORN  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            Ok(Instruction::OrnPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x800200 => {
            // NOR  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            Ok(Instruction::NorPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0x800210 => {
            // NAND  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            Ok(Instruction::NandPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0xc00000 => {
            // MOVS (unpredicated)
            // MOVS  <Pd>.B, <Pn>.B
            // ORRS  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            if Pn == Pm && Pm == Pg {
                return Ok(Instruction::MovsPPOrrsPPPpZ {
                    Pd: PReg::new(Pd),
                    Pn: PReg::new(Pn),
                });
            }
            Ok(Instruction::OrrsPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0xc00010 => {
            // ORNS  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            Ok(Instruction::OrnsPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0xc00200 => {
            // NORS  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            Ok(Instruction::NorsPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        0xc00210 => {
            // NANDS  <Pd>.B, <Pg>/Z, <Pn>.B, <Pm>.B
            Ok(Instruction::NandsPPPpZ {
                Pd: PReg::new(Pd),
                Pg: PReg::new(Pg),
                Pn: PReg::new(Pn),
                Pm: PReg::new(Pm),
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

