fn decode_sve_int_rotate_imm(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff20fc00 != 0x4203400 {
        return Err(DecodeError::Unallocated);
    }
    // 000|0010|0|tszh=xx|1|tszl=xx|imm3=xxx|001|101|Zm=xxxxx|Zdn=xxxxx
    // XAR  <Zdn>.<T>, <Zdn>.<T>, <Zm>.<T>, #<const>
    let tszh: u8 = ((bits >> 22) & 0x3) as u8;
    let tszl: u8 = ((bits >> 19) & 0x3) as u8;
    let tsize: u8 = tszh << 2 | tszl;
    if tsize == 0b0000 {
        return Err(DecodeError::UNDEF);
    }
    let esize: u8 = 8 << tsize.ilog2();
    let Zm: u8 = ((bits >> 5) & 0x1f) as u8;
    let Zdn: u8 = (bits & 0x1f) as u8;
    let imm3: u8 = ((bits >> 16) & 0x7) as u8;
    let rot: i64 = 2 * esize as i64 - (tsize << 3 | imm3) as i64;
    Ok(Instruction::XarZZzi {
        Zdn: ZReg::new(Zdn),
        T: match tszh << 2 | tszl {
            0b0001 => Arrangement::element(ElementWidth::B),
            0b0010 | 0b0011 => Arrangement::element(ElementWidth::H),
            0b0100..=0b0111 => Arrangement::element(ElementWidth::S),
            0b1000..=0b1111 => Arrangement::element(ElementWidth::D),
            _ => return Err(DecodeError::Unallocated),
        },
        Zm: ZReg::new(Zm),
        const_: rot,
    })
}

