fn decode_sve_int_sel_vvv(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff20c000 != 0x520c000 {
        return Err(DecodeError::Unallocated);
    }
    // 000|0010|1|size=xx|1|Zm=xxxxx|11|Pv=xxxx|Zn=xxxxx|Zd=xxxxx
    // MOV (vector, predicated)
    // MOV  <Zd>.<T>, <Pv>/M, <Zn>.<T>
    // SEL (vectors)
    // SEL  <Zd>.<T>, <Pv>, <Zn>.<T>, <Zm>.<T>
    let size: u8 = ((bits >> 22) & 0x3) as u8;
    let Zm: u8 = ((bits >> 16) & 0x1f) as u8;
    let Pv: u8 = ((bits >> 10) & 0xf) as u8;
    let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
    let Zd: u8 = (bits & 0x1f) as u8;
    if Zd == Zm {
        return Ok(Instruction::MovZPZSelZPZz {
            Zd: ZReg::new(Zd),
            T: match size {
                0b00 => Arrangement::element(ElementWidth::B),
                0b01 => Arrangement::element(ElementWidth::H),
                0b10 => Arrangement::element(ElementWidth::S),
                _ => Arrangement::element(ElementWidth::D),
            },
            Pv: PReg::new(Pv),
            Zn: ZReg::new(Zn),
        });
    }
    Ok(Instruction::SelZPZz {
        Zd: ZReg::new(Zd),
        T: match size {
            0b00 => Arrangement::element(ElementWidth::B),
            0b01 => Arrangement::element(ElementWidth::H),
            0b10 => Arrangement::element(ElementWidth::S),
            _ => Arrangement::element(ElementWidth::D),
        },
        Pv: PReg::new(Pv),
        Zn: ZReg::new(Zn),
        Zm: ZReg::new(Zm),
    })
}

