fn decode_sve_intx_cadd(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff3ef800 != 0x4500d800 {
        return Err(DecodeError::Unallocated);
    }
    // 010|0010|1|size=xx|0|0000|op=x|11|011|rot=x|Zm=xxxxx|Zdn=xxxxx
    let size: u8 = ((bits >> 22) & 0x3) as u8;
    let rot: u8 = ((bits >> 10) & 0x1) as u8;
    let Zm: u8 = ((bits >> 5) & 0x1f) as u8;
    let Zdn: u8 = (bits & 0x1f) as u8;
    match bits & 0x10000 {
        0 => {
            // CADD  <Zdn>.<T>, <Zdn>.<T>, <Zm>.<T>, <const>
            Ok(Instruction::CaddZZz {
                Zdn: ZReg::new(Zdn),
                T: match size {
                    0b00 => Arrangement::element(ElementWidth::B),
                    0b01 => Arrangement::element(ElementWidth::H),
                    0b10 => Arrangement::element(ElementWidth::S),
                    _ => Arrangement::element(ElementWidth::D),
                },
                Zm: ZReg::new(Zm),
                const_: if rot == 0 { 90 } else { 270 },
            })
        }
        0x10000 => {
            // SQCADD  <Zdn>.<T>, <Zdn>.<T>, <Zm>.<T>, <const>
            Ok(Instruction::SqcaddZZz {
                Zdn: ZReg::new(Zdn),
                T: match size {
                    0b00 => Arrangement::element(ElementWidth::B),
                    0b01 => Arrangement::element(ElementWidth::H),
                    0b10 => Arrangement::element(ElementWidth::S),
                    _ => Arrangement::element(ElementWidth::D),
                },
                Zm: ZReg::new(Zm),
                const_: if rot == 0 { 90 } else { 270 },
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

fn decode_sve_intx_cdot(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff20f000 != 0x44001000 {
        return Err(DecodeError::Unallocated);
    }
    // 010|0010|0|size=xx|0|Zm=xxxxx|0|001|rot=xx|Zn=xxxxx|Zda=xxxxx
    // CDOT (vectors)
    // CDOT  <Zda>.<T>, <Zn>.<Tb>, <Zm>.<Tb>, <const>
    let size: u8 = ((bits >> 22) & 0x3) as u8;
    if size & 0x2 == 0x0 {
        return Err(DecodeError::UNDEF);
    }
    let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
    let Zm: u8 = ((bits >> 16) & 0x1f) as u8;
    let Zda: u8 = (bits & 0x1f) as u8;
    let rot: u8 = ((bits >> 10) & 0x3) as u8;
    Ok(Instruction::CdotZZzz {
        Zda: ZReg::new(Zda),
        T: if (size & 0x1) == 0 {
            Arrangement::element(ElementWidth::S)
        } else {
            Arrangement::element(ElementWidth::D)
        },
        Zn: ZReg::new(Zn),
        Tb: if (size & 0x1) == 0 {
            Arrangement::element(ElementWidth::B)
        } else {
            Arrangement::element(ElementWidth::H)
        },
        Zm: ZReg::new(Zm),
        const_: match rot {
            0b00 => 0,
            0b01 => 90,
            0b10 => 180,
            _ => 270,
        },
    })
}

fn decode_sve_intx_cdot_by_indexed_elem(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffa0f000 != 0x44a04000 {
        return Err(DecodeError::Unallocated);
    }
    // 010|0010|0|size=1x|1|i2=xx|Zm=xxx|0100|rot=xx|Zn=xxxxx|Zda=xxxxx
    match bits & 0xc00000 {
        0x800000 => {
            // CDOT (indexed)
            // CDOT  <Zda>.S, <Zn>.B, <Zm>.B[<imm>], <const>
            let i2: u8 = ((bits >> 19) & 0x3) as u8;
            let Zm: u8 = ((bits >> 16) & 0x7) as u8;
            let rot: u8 = ((bits >> 10) & 0x3) as u8;
            let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
            let Zda: u8 = (bits & 0x1f) as u8;
            Ok(Instruction::CdotZZzziS {
                Zda: ZReg::new(Zda),
                Zn: ZReg::new(Zn),
                Zm: ZReg::new(Zm),
                imm: i2,
                const_: match rot {
                    0b00 => 0,
                    0b01 => 90,
                    0b10 => 180,
                    _ => 270,
                },
            })
        }
        0xc00000 => {
            // CDOT (indexed)
            // CDOT  <Zda>.D, <Zn>.H, <Zm>.H[<imm>], <const>
            let i1: u8 = ((bits >> 20) & 0x1) as u8;
            let Zm: u8 = ((bits >> 16) & 0xf) as u8;
            let rot: u8 = ((bits >> 10) & 0x3) as u8;
            let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
            let Zda: u8 = (bits & 0x1f) as u8;
            Ok(Instruction::CdotZZzziD {
                Zda: ZReg::new(Zda),
                Zn: ZReg::new(Zn),
                Zm: ZReg::new(Zm),
                imm: i1 != 0,
                const_: match rot {
                    0b00 => 0,
                    0b01 => 90,
                    0b10 => 180,
                    _ => 270,
                },
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

