fn decode_sve_intx_cmla(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff20e000 != 0x44002000 {
        return Err(DecodeError::Unallocated);
    }
    // 010|0010|0|size=xx|0|Zm=xxxxx|0|01|op=x|rot=xx|Zn=xxxxx|Zda=xxxxx
    let size: u8 = ((bits >> 22) & 0x3) as u8;
    let Zm: u8 = ((bits >> 16) & 0x1f) as u8;
    let rot: u8 = ((bits >> 10) & 0x3) as u8;
    let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
    let Zda: u8 = (bits & 0x1f) as u8;
    match bits & 0x1000 {
        0 => {
            // CMLA (vectors)
            // CMLA  <Zda>.<T>, <Zn>.<T>, <Zm>.<T>, <const>
            Ok(Instruction::CmlaZZzz {
                Zda: ZReg::new(Zda),
                T: match size {
                    0b00 => Arrangement::element(ElementWidth::B),
                    0b01 => Arrangement::element(ElementWidth::H),
                    0b10 => Arrangement::element(ElementWidth::S),
                    _ => Arrangement::element(ElementWidth::D),
                },
                Zn: ZReg::new(Zn),
                Zm: ZReg::new(Zm),
                const_: match rot {
                    0b00 => 0,
                    0b01 => 90,
                    0b10 => 180,
                    _ => 270,
                },
            })
        }
        0x1000 => {
            // SQRDCMLAH (vectors)
            // SQRDCMLAH  <Zda>.<T>, <Zn>.<T>, <Zm>.<T>, <const>
            Ok(Instruction::SqrdcmlahZZzz {
                Zda: ZReg::new(Zda),
                T: match size {
                    0b00 => Arrangement::element(ElementWidth::B),
                    0b01 => Arrangement::element(ElementWidth::H),
                    0b10 => Arrangement::element(ElementWidth::S),
                    _ => Arrangement::element(ElementWidth::D),
                },
                Zn: ZReg::new(Zn),
                Zm: ZReg::new(Zm),
                const_: match rot {
                    0b00 => 0,
                    0b01 => 90,
                    0b10 => 180,
                    _ => 270,
                },
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

