fn decode_sve_intx_dot(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff20f800 != 0x44000000 {
        return Err(DecodeError::Unallocated);
    }
    // 010|0010|0|size=xx|0|Zm=xxxxx|0|0000|U=x|Zn=xxxxx|Zda=xxxxx
    let Zm: u8 = ((bits >> 16) & 0x1f) as u8;
    let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
    let Zda: u8 = (bits & 0x1f) as u8;
    if (bits & 0xc00400) == 0x400000 {
        // SDOT (2-way, vectors)
        // SDOT  <Zda>.H, <Zn>.B, <Zm>.B
        Ok(Instruction::SdotZ16ZzzH {
            Zda: ZReg::new(Zda),
            Zn: ZReg::new(Zn),
            Zm: ZReg::new(Zm),
        })
    } else if (bits & 0xc00400) == 0x400400 {
        // UDOT (2-way, vectors)
        // UDOT  <Zda>.H, <Zn>.B, <Zm>.B
        Ok(Instruction::UdotZ16ZzzH {
            Zda: ZReg::new(Zda),
            Zn: ZReg::new(Zn),
            Zm: ZReg::new(Zm),
        })
    } else if (bits & 0x800400) == 0x800000 {
        // SDOT (4-way, vectors)
        // SDOT  <Zda>.<T>, <Zn>.<Tb>, <Zm>.<Tb>
        let size: u8 = ((bits >> 22) & 0x3) as u8;
        Ok(Instruction::SdotZZzz {
            Zda: ZReg::new(Zda),
            T: if (size & 0x1) == 0 {
                Arrangement::element(ElementWidth::S)
            } else {
                Arrangement::element(ElementWidth::D)
            },
            Zn: ZReg::new(Zn),
            Tb: if (size & 0x1) == 0 {
                Arrangement::element(ElementWidth::B)
            } else {
                Arrangement::element(ElementWidth::H)
            },
            Zm: ZReg::new(Zm),
        })
    } else if (bits & 0x800400) == 0x800400 {
        // UDOT (4-way, vectors)
        // UDOT  <Zda>.<T>, <Zn>.<Tb>, <Zm>.<Tb>
        let size: u8 = ((bits >> 22) & 0x3) as u8;
        Ok(Instruction::UdotZZzz {
            Zda: ZReg::new(Zda),
            T: if (size & 0x1) == 0 {
                Arrangement::element(ElementWidth::S)
            } else {
                Arrangement::element(ElementWidth::D)
            },
            Zn: ZReg::new(Zn),
            Tb: if (size & 0x1) == 0 {
                Arrangement::element(ElementWidth::B)
            } else {
                Arrangement::element(ElementWidth::H)
            },
            Zm: ZReg::new(Zm),
        })
    } else {
        Err(DecodeError::Unallocated)
    }
}

