fn decode_sve_intx_perm_extract_i(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffe0e000 != 0x5600000 {
        return Err(DecodeError::Unallocated);
    }
    // 000|0010|10|1|1|imm8h=xxxxx|000|imm8l=xxx|Zn=xxxxx|Zd=xxxxx
    // EXT  <Zd>.B, { <Zn1>.B, <Zn2>.B }, #<imm>
    let Zd: u8 = (bits & 0x1f) as u8;
    let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
    let imm8h: u8 = ((bits >> 16) & 0x1f) as u8;
    let imm8l: u8 = ((bits >> 10) & 0x7) as u8;
    let position: u16 = ((imm8h as u16) << 3 | imm8l as u16) * 8;
    let raw_imm: u8 = imm8h << 3 | imm8l;
    Ok(Instruction::ExtZZiCon {
        Zd: ZReg::new(Zd),
        Zn1: ZReg::new(Zn),
        Zn2: ZReg::new((Zn + 1) % 32),
        imm: raw_imm,
    })
}

