fn decode_sve_intx_sra(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff20f000 != 0x4500e000 {
        return Err(DecodeError::Unallocated);
    }
    // 010|0010|1|tszh=xx|0|tszl=xx|imm3=xxx|11|10|R=x|U=x|Zn=xxxxx|Zda=xxxxx
    let tszh: u8 = ((bits >> 22) & 0x3) as u8;
    let tszl: u8 = ((bits >> 19) & 0x3) as u8;
    let tsize: u8 = tszh << 2 | tszl;
    if tsize == 0b0000 {
        return Err(DecodeError::UNDEF);
    }
    let esize: u8 = 8 << tsize.ilog2();
    let Zn: u8 = ((bits >> 5) & 0x1f) as u8;
    let Zda: u8 = (bits & 0x1f) as u8;
    let imm3: u8 = ((bits >> 16) & 0x7) as u8;
    let shift: i64 = 2 * esize as i64 - (tsize << 3 | imm3) as i64;
    match bits & 0xc00 {
        0 => {
            // SSRA  <Zda>.<T>, <Zn>.<T>, #<const>
            Ok(Instruction::SsraZZi {
                Zda: ZReg::new(Zda),
                T: match tszh << 2 | tszl {
                    0b0001 => Arrangement::element(ElementWidth::B),
                    0b0010 | 0b0011 => Arrangement::element(ElementWidth::H),
                    0b0100..=0b0111 => Arrangement::element(ElementWidth::S),
                    0b1000..=0b1111 => Arrangement::element(ElementWidth::D),
                    _ => return Err(DecodeError::Unallocated),
                },
                Zn: ZReg::new(Zn),
                const_: shift,
            })
        }
        0x400 => {
            // USRA  <Zda>.<T>, <Zn>.<T>, #<const>
            Ok(Instruction::UsraZZi {
                Zda: ZReg::new(Zda),
                T: match tszh << 2 | tszl {
                    0b0001 => Arrangement::element(ElementWidth::B),
                    0b0010 | 0b0011 => Arrangement::element(ElementWidth::H),
                    0b0100..=0b0111 => Arrangement::element(ElementWidth::S),
                    0b1000..=0b1111 => Arrangement::element(ElementWidth::D),
                    _ => return Err(DecodeError::Unallocated),
                },
                Zn: ZReg::new(Zn),
                const_: shift,
            })
        }
        0x800 => {
            // SRSRA  <Zda>.<T>, <Zn>.<T>, #<const>
            Ok(Instruction::SrsraZZi {
                Zda: ZReg::new(Zda),
                T: match tszh << 2 | tszl {
                    0b0001 => Arrangement::element(ElementWidth::B),
                    0b0010 | 0b0011 => Arrangement::element(ElementWidth::H),
                    0b0100..=0b0111 => Arrangement::element(ElementWidth::S),
                    0b1000..=0b1111 => Arrangement::element(ElementWidth::D),
                    _ => return Err(DecodeError::Unallocated),
                },
                Zn: ZReg::new(Zn),
                const_: shift,
            })
        }
        0xc00 => {
            // URSRA  <Zda>.<T>, <Zn>.<T>, #<const>
            Ok(Instruction::UrsraZZi {
                Zda: ZReg::new(Zda),
                T: match tszh << 2 | tszl {
                    0b0001 => Arrangement::element(ElementWidth::B),
                    0b0010 | 0b0011 => Arrangement::element(ElementWidth::H),
                    0b0100..=0b0111 => Arrangement::element(ElementWidth::S),
                    0b1000..=0b1111 => Arrangement::element(ElementWidth::D),
                    _ => return Err(DecodeError::Unallocated),
                },
                Zn: ZReg::new(Zn),
                const_: shift,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

fn decode_sve_mem_32b_acqfill(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffe0e000 != 0x85806000 {
        return Err(DecodeError::Unallocated);
    }
    // 100|0010|11|00|imm8h=xxxxx|011|imm8l=xxx|Rn=xxxxx|Zt=xxxxx
    // LDAPRO  <Zt>, [<Xn|SP>{, #<imm>}]
    let Zt: u8 = (bits & 0x1f) as u8;
    let Rn: u8 = ((bits >> 5) & 0x1f) as u8;
    let imm8h: u8 = ((bits >> 16) & 0x1f) as u8;
    let imm8l: u8 = ((bits >> 10) & 0x7) as u8;
    let imm: u8 = imm8h << 3 | imm8l;
    Ok(Instruction::LdaproZBi {
        Zt: ZReg::new(Zt),
        Xn: Rn.into(),
        imm: imm as i64 * 32,
    })
}

fn decode_sve_mem_32b_fill(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffc0e000 != 0x85804000 {
        return Err(DecodeError::Unallocated);
    }
    // 100|0010|11|0|imm9h=xxxxxx|010|imm9l=xxx|Rn=xxxxx|Zt=xxxxx
    // LDR (vector)
    // LDR  <Zt>, [<Xn|SP>{, #<imm>, MUL VL}]
    let Zt: u8 = (bits & 0x1f) as u8;
    let Rn: u8 = ((bits >> 5) & 0x1f) as u8;
    let imm9h: u8 = ((bits >> 16) & 0x3f) as u8;
    let imm9l: u8 = ((bits >> 10) & 0x7) as u8;
    let imm: i16 = asl::SInt(9, (imm9h as u128) << 3 | imm9l as u128) as i16;
    Ok(Instruction::LdrZBi {
        Zt: ZReg::new(Zt),
        Xn: Rn.into(),
        imm,
    })
}

