fn decode_sve_mem_32b_pfill(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffc0e010 != 0x85800000 {
        return Err(DecodeError::Unallocated);
    }
    // 100|0010|11|0|imm9h=xxxxxx|000|imm9l=xxx|Rn=xxxxx|0|Pt=xxxx
    // LDR (predicate)
    // LDR  <Pt>, [<Xn|SP>{, #<imm>, MUL VL}]
    let Pt: u8 = (bits & 0xf) as u8;
    let Rn: u8 = ((bits >> 5) & 0x1f) as u8;
    let imm9h: u8 = ((bits >> 16) & 0x3f) as u8;
    let imm9l: u8 = ((bits >> 10) & 0x7) as u8;
    let imm: i16 = asl::SInt(9, (imm9h as u128) << 3 | imm9l as u128) as i16;
    Ok(Instruction::LdrPBi {
        Pt: PReg::new(Pt),
        Xn: Rn.into(),
        imm,
    })
}

